package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.text.InputType;import android.widget.*;import org.json.*;
public final class ProfileEditor {
 private static String manage(Activity a,String action,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,req.toString());}
 private static void error(Activity a,Exception e){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Player profile").setMessage(String.valueOf(e.getCause()==null?e:e.getCause())).setPositiveButton("Close",null).show();}
 public static void attach(Activity a,LinearLayout col,JSONObject p){StatEditor.attach(a,col,p);button(a,col,p,"Copy Body & Motion","model");button(a,col,p,"Name · Shirt Name · Age","identity");}
 public static void attachTraits(Activity a,LinearLayout col,JSONObject p){button(a,col,p,"Preferred Foot · Weak Foot · Injury Resistance","traits");}
 public static void button(Activity a,LinearLayout col,JSONObject p,String label,String kind){Button b=new Button(a);b.setText(label);b.setAllCaps(false);b.setOnClickListener(v->{b.setEnabled(false);open(a,p,kind,b);});col.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 public static void open(Activity a,JSONObject player,String section){open(a,player,section,null);}
 private static void open(Activity a,JSONObject player,String section,Button busy){new Thread(()->{try{JSONObject req=new JSONObject(player.toString()).put("section",section);JSONObject result=new JSONObject(manage(a,"ui711_profile_get",req));a.runOnUiThread(()->{if(busy!=null)busy.setEnabled(true);if(!a.isFinishing())form(a,player,result,section);});}catch(Exception e){a.runOnUiThread(()->{if(busy!=null)busy.setEnabled(true);error(a,e);});}},"PlayerProfileLoad").start();}
 private static void label(Activity a,LinearLayout col,String text){TextView t=new TextView(a);t.setText(text);t.setPadding(0,12,0,4);col.addView(t);}
 private static EditText input(Activity a,LinearLayout col,String title,String value,boolean number){label(a,col,title);EditText e=new EditText(a);e.setSingleLine(true);e.setInputType(number?InputType.TYPE_CLASS_NUMBER:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS);e.setText(value);col.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 private static Spinner select(Activity a,LinearLayout col,String title,String[] names,int value){label(a,col,title);Spinner s=new Spinner(a);ArrayAdapter<String> ad=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,names);ad.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(ad);s.setSelection(Math.max(0,Math.min(names.length-1,value)));col.addView(s,new LinearLayout.LayoutParams(-1,-2));return s;}
 private static Spinner catalogue(Activity a,LinearLayout col,String title,JSONArray rows,long current){String[] names=new String[rows.length()+1];names[0]="Keep current selection";int at=0;for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);names[i+1]=r.optString("name");if(r.optLong("id")==current)at=i+1;}return select(a,col,title,names,at);}
 private static long selected(Spinner s,JSONArray rows){int i=s.getSelectedItemPosition();return i==0?0:rows.optJSONObject(i-1).optLong("id");}
 private static void form(Activity a,JSONObject player,JSONObject data,String section){try{JSONObject previous=data.optJSONObject("values");if(previous==null)previous=new JSONObject();final JSONObject old=previous;LinearLayout col=new LinearLayout(a);col.setOrientation(1);int pad=Math.round(16*a.getResources().getDisplayMetrics().density);col.setPadding(pad,pad,pad,pad);ScrollView scroll=new ScrollView(a);scroll.addView(col);label(a,col,"Save before Enter Game, then close and reopen the app.");EditText name=null,shirt=null,age=null;Spinner model=null,club=null,nation=null,foot=null,usage=null,accuracy=null,injury=null;JSONArray models=data.optJSONArray("models"),clubs=data.optJSONArray("clubs"),countries=data.optJSONArray("countries");
 if(section.equals("model")){label(a,col,"Current source: "+data.optString("model_source_name"));label(a,col,"Copies body proportions, height, weight, preferred foot and the source card's run, dribble, set-piece, celebration and AI motion settings. Keeps this card's face, abilities and position. Replaces previous body-size edits for this card.");model=catalogue(a,col,"Copy from",models,old.optLong("model_source",0));}
 if(section.equals("identity")){name=input(a,col,"Player name",data.optString("current_name"),false);shirt=input(a,col,"Shirt name (leave blank to keep)",data.optString("current_shirt"),false);age=input(a,col,"Age · 15–63",String.valueOf(data.optInt("age")),true);}
 if(section.equals("affiliation")){label(a,col,"Changes the club and national flag shown on this card. Your squad stays the same.");club=catalogue(a,col,"Club",clubs,old.optLong("club",0));nation=catalogue(a,col,"Nationality",countries,old.optLong("nation",0));}
 if(section.equals("traits")){JSONObject t=data.getJSONObject("traits");foot=select(a,col,"Preferred foot",new String[]{"Right","Left"},t.optInt("43"));usage=select(a,col,"Weak Foot Usage",new String[]{"0","1","2","3"},t.optInt("45"));accuracy=select(a,col,"Weak Foot Accuracy",new String[]{"0","1","2","3"},t.optInt("33"));injury=select(a,col,"Injury Resistance",new String[]{"0","1","2","3"},t.optInt("42"));}
 final EditText fn=name,fs=shirt,fa=age;final Spinner fm=model,fc=club,ft=nation,ff=foot,fu=usage,fw=accuracy,fi=injury;AlertDialog d=new AlertDialog.Builder(a).setTitle(section.equals("model")?"Copy Body & Motion":section.equals("identity")?"Player Identity":section.equals("traits")?"Foot & Fitness":"Club & Nationality").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setOnClickListener(v->{try{JSONObject values=new JSONObject();if(fn!=null){if(fn.getText().toString().trim().length()>0&&!fn.getText().toString().trim().equals(data.optString("current_name")))values.put("name",fn.getText().toString().trim());if(fs.getText().toString().trim().length()>0&&!fs.getText().toString().trim().equals(data.optString("current_shirt")))values.put("shirt",fs.getText().toString().trim());int years=Integer.parseInt(fa.getText().toString());if(years!=data.optInt("age"))values.put("age",years);}if(fm!=null){long id=selected(fm,models);if(id==0){d.dismiss();return;}values.put("model_source",String.valueOf(id));}if(fc!=null){long c=selected(fc,clubs),n=selected(ft,countries);if(c!=0)values.put("club",c);if(n!=0)values.put("nation",n);}if(ff!=null)values.put("traits",new JSONObject().put("43",ff.getSelectedItemPosition()).put("45",fu.getSelectedItemPosition()).put("33",fw.getSelectedItemPosition()).put("42",fi.getSelectedItemPosition()));JSONObject req=new JSONObject(player.toString()).put("values",values);d.getButton(-1).setEnabled(false);new Thread(()->{try{JSONObject r=new JSONObject(manage(a,"ui711_profile_apply",req));if(!r.optBoolean("saved"))throw new Exception("Save not confirmed");a.runOnUiThread(()->{d.dismiss();Toast.makeText(a,"Saved. Reopen the app.",Toast.LENGTH_LONG).show();});}catch(Exception e){a.runOnUiThread(()->{d.getButton(-1).setEnabled(true);error(a,e);});}},"PlayerProfileSave").start();}catch(Exception e){error(a,e);}});
 }catch(Exception e){error(a,e);}}
}
